/**
 * @file src/lib/combatStatStageDisplay.ts
 * Affichage HUD des stages de stats en combat.
 */

import { formatNumber } from '../../formatters.ts';
import { STATUS_EFFECTS } from '../../constants/balance/talentsAndCombat.ts';
import type { ICreature } from '../types/creature.js';
import type { CombatStatKey } from '../types/combat.ts';

export type HudStatTint = 'buff' | 'nerf' | null;

export interface HudCombatStatDisplay {
    neutral: number;
    effective: number;
    tint: HudStatTint;
    text: string;
}

const STAT_SHORT_FR: Record<CombatStatKey, string> = {
    attack: 'Att',
    spattack: 'Atq.Sp',
    defense: 'Déf',
    spdefense: 'Déf.Sp',
    speed: 'Vit',
    accuracy: 'Préc',
    evasion: 'Esqu',
};

const STAT_SHORT_EN: Record<CombatStatKey, string> = {
    attack: 'Atk',
    spattack: 'Sp.Atk',
    defense: 'Def',
    spdefense: 'Sp.Def',
    speed: 'Spe',
    accuracy: 'Acc',
    evasion: 'Eva',
};

const HUD_STAT_KEYS: CombatStatKey[] = ['attack', 'spattack', 'defense', 'spdefense', 'speed'];
const STAGE_BADGE_KEYS: CombatStatKey[] = [...HUD_STAT_KEYS, 'accuracy', 'evasion'];

export function formatHudStatWithStage(baseValue: number, stage: number): string {
    const formatted = formatNumber(baseValue);
    if (!stage) return formatted;
    const sign = stage > 0 ? '+' : '';
    return `${formatted} (${sign}${stage})`;
}

export function getCreatureCombatStatStage(creature: ICreature | null | undefined, stat: CombatStatKey): number {
    if (!creature || typeof creature.getCombatStatStage !== 'function') return 0;
    return creature.getCombatStatStage(stat);
}

/** Status-only multiplier for a HUD stat (excludes talents and combat stages). */
export function getStatusStatMultiplier(creature: ICreature | null | undefined, stat: CombatStatKey): number {
    if (!creature?.hasStatusEffect?.() || !creature.statusEffect) return 1;
    const type = creature.statusEffect.type;

    if (stat === 'attack' || stat === 'spattack') {
        if (type === STATUS_EFFECTS.SCARED) return 0.60;
        if (type === STATUS_EFFECTS.ENRAGED) return 1.30;
        if (type === STATUS_EFFECTS.PUNCHER) return 2.0;
        return 1;
    }
    if (stat === 'defense' || stat === 'spdefense') {
        if (type === STATUS_EFFECTS.REINFORCED) return 1.25;
        return 1;
    }
    if (stat === 'speed') {
        if (type === STATUS_EFFECTS.ENRAGED) return 1.15;
        if (type === STATUS_EFFECTS.PARALYZED) return 0.75;
        if (type === STATUS_EFFECTS.MIRED) return 0.60;
        return 1;
    }
    return 1;
}

function getStageMultiplier(creature: ICreature | null | undefined, stat: CombatStatKey): number {
    if (creature && typeof creature.getCombatStatStageMultiplier === 'function') {
        return creature.getCombatStatStageMultiplier(stat);
    }
    const stage = getCreatureCombatStatStage(creature, stat);
    if (!stage) return 1;
    return Math.max(0.1, 1 + stage * 0.10);
}

function resolveHudStatTint(neutral: number, effective: number): HudStatTint {
    if (effective > neutral) return 'buff';
    if (effective < neutral) return 'nerf';
    return null;
}

export function resolveHudCombatStat(
    creature: ICreature | null | undefined,
    stat: CombatStatKey,
    rawValue: number,
): HudCombatStatDisplay {
    const raw = Number(rawValue) || 0;
    const statusMult = getStatusStatMultiplier(creature, stat);
    const stageMult = getStageMultiplier(creature, stat);
    const isEnemy = !!creature?.isEnemy;

    let neutral: number;
    let effective: number;

    if (isEnemy) {
        neutral = raw;
        effective = Math.floor(raw * statusMult * stageMult);
    } else if (stat === 'speed') {
        effective = raw;
        neutral = (statusMult > 0 && stageMult > 0) ? Math.floor(raw / statusMult / stageMult) : raw;
    } else {
        neutral = statusMult > 0 ? Math.floor(raw / statusMult) : raw;
        effective = Math.floor(raw * stageMult);
    }

    return {
        neutral,
        effective,
        tint: resolveHudStatTint(neutral, effective),
        text: formatNumber(effective),
    };
}

export function buildCombatStatStageBadgesHtml(
    creature: ICreature | null | undefined,
    lang: 'fr' | 'en' = 'fr',
): string {
    if (!creature || typeof creature.getCombatStatStage !== 'function') return '';
    const labels = lang === 'en' ? STAT_SHORT_EN : STAT_SHORT_FR;
    const parts: string[] = [];
    for (const stat of STAGE_BADGE_KEYS) {
        const stage = creature.getCombatStatStage(stat);
        if (!stage) continue;
        const sign = stage > 0 ? '+' : '';
        const dir = stage > 0 ? 'up' : 'down';
        parts.push(
            `<span class="stat-stage-badge stat-stage-${dir}" title="${labels[stat]} ${sign}${stage}">${labels[stat]}${sign}${stage}</span>`,
        );
    }
    return parts.join('');
}

export function hasAnyCombatStatStage(creature: ICreature | null | undefined): boolean {
    if (!creature || typeof creature.getCombatStatStage !== 'function') return false;
    return STAGE_BADGE_KEYS.some((stat) => creature.getCombatStatStage(stat) !== 0);
}
