/**
 * @file src/ui/breakpoints.ts
 * Breakpoints responsive — garder aligné avec mobile.css @media (max-width: 1200px)
 * et index.html matchMedia (min-width: 1201px).
 */

export const MOBILE_MAX_WIDTH_PX = 1200;

export const MOBILE_MEDIA_QUERY = `(max-width: ${MOBILE_MAX_WIDTH_PX}px)` as const;
export const DESKTOP_MEDIA_QUERY = `(min-width: ${MOBILE_MAX_WIDTH_PX + 1}px)` as const;

/** Modales ouvertes — garder aligné avec mobile.css body:has() (scroll lock) et inset modales. */
export const MODAL_OPEN_SELECTOR =
    '.modal-overlay.show, .stats-modal.show:not(.relic-modal-passive), .quest-completion-modal.show, '
    + '.save-slot-boot-modal.show, #captureModal.show, .compact-popup.show, .js-modal-overlay.show';

export function isMobileViewport(): boolean {
    if (typeof window === 'undefined') return false;
    if (typeof window.matchMedia === 'function') {
        return window.matchMedia(MOBILE_MEDIA_QUERY).matches;
    }
    return window.innerWidth <= MOBILE_MAX_WIDTH_PX;
}
